    // The calculation categorizes the level as "HIGH" or "NORMAL".
    auto statusCalc = react(
        [&]() {
            ++recomputeCount;
            lastProcessed = sensor.get();
            return (lastProcessed >= levelThreshold) ? std::string("HIGH")
                                                     : std::string("NORMAL");
        },
        sensor,
        trigger::filter([&](double newVal, double /*oldVal*/) {
            return std::fabs(newVal - lastProcessed) >= diffThreshold;
        }));

    // Initialize by reading once so that a valid value is present
    (void)statusCalc.get();

    // 4. Apply filter - already applied via trigger::filter above

    // 5. Update sensor with first value
    sensor.value(firstUpdate);

    // 6. Record recompute count after first update
    int countAfterFirst = recomputeCount;

    // 7. Update sensor with second value
    sensor.value(secondUpdate);

    // 8. Record recompute count after second update
    int countAfterSecond = recomputeCount;

    // 9. Get final status
    std::string finalStatus = statusCalc.get();

    // 10. Return final status and counts
    return std::make_tuple(finalStatus, countAfterFirst, countAfterSecond);
}

}  // namespace test_reaction

