#pragma once

#include <reaction/reaction.h>

namespace test_reaction {

class IdTrackedFields : public reaction::FieldBase {
public:
    explicit IdTrackedFields(int value)
        : m_value(field(value)) {
    }

    reaction::Var<int>& valueField() {
        return m_value;
    }

private:
    reaction::Var<int> m_value;
};

struct FieldIdComparison {
    uint64_t firstIdFirstRead;
    uint64_t firstIdSecondRead;
    uint64_t secondId;
};

inline FieldIdComparison test_field_unique_id(int initialFirst, int initialSecond) {
    // 1. Create first IdTrackedFields instance
    IdTrackedFields first(initialFirst);

    // 2. Create second IdTrackedFields instance
    IdTrackedFields second(initialSecond);

    // 3. Read ID from first instance
    uint64_t firstIdFirstRead = static_cast<uint64_t>(first.getObjectId());

    // 4. Read ID from first instance again to verify stability
    uint64_t firstIdSecondRead = static_cast<uint64_t>(first.getObjectId());

    // 5. Read ID from second instance to verify uniqueness
    uint64_t secondId = static_cast<uint64_t>(second.getObjectId());

    // 6. Update reactive fields to avoid unused variable warnings
    first.valueField().value(initialFirst + 1);
    second.valueField().value(initialSecond + 1);

    // 7. Return field ID comparison
    return FieldIdComparison{firstIdFirstRead, firstIdSecondRead, secondId};
}

}  // namespace test_reaction

