namespace test_reaction {

struct SmallPayload {
    int value;
    bool operator!=(const SmallPayload& other) const = default;
};

struct LargePayload {
    std::array<int, 64> data{};
    bool operator!=(const LargePayload& other) const = default;
};

struct SboStorageStatus {
    bool updateReportedChange;
    bool smallUsingSBO;
    std::size_t smallStackUsage;
    bool largeInitialized;
    bool largeUsingSBO;
};

inline SboStorageStatus test_sbo_storage_info(int initialSmall,
                                              int updatedSmall,
                                              int largeSeed) {
    using reaction::memory::SBOResource;

    // 1. Lambda to make large payload from a seed
    auto make_large = [](int seed) {
        LargePayload payload;
        for (std::size_t i = 0; i < payload.data.size(); ++i) {
            payload.data[i] = seed + static_cast<int>(i);
        }
        return payload;
    };

    // 2. Create small SBOResource
    SBOResource<SmallPayload> small_res(SmallPayload{initialSmall});

    // 3. Create large SBOResource
    SBOResource<LargePayload> large_res(make_large(largeSeed));

    // 4. Update small resource value
    bool updateReportedChange =
        small_res.update(SmallPayload{updatedSmall});  // returns true if value changed

    // 5. Get storage information for small resource
    auto small_info = small_res.getStorageInfo();

    // 6. Get storage information for large resource
    auto large_info = large_res.getStorageInfo();

    // 7. Return SBO storage status
    SboStorageStatus status{
        updateReportedChange,
        small_info.using_sbo,
        small_info.stack_usage,
        large_info.initialized,
        large_info.using_sbo};

    return status;
}

}  // namespace test_reaction

