inline SboTraitSummary analyze_sbo_traits() {
    using namespace reaction::memory;

    // Query SBOTraits for the three POD types
    using TinyTraits   = SBOTraits<TinyPod>;
    using MediumTraits = SBOTraits<MediumPod>;
    using LargeTraits  = SBOTraits<LargePod>;

    SboTraitSummary summary{};

    // For TinyPod, check if it always uses SBO or is forced to heap.
    summary.tinyAlwaysSbo = TinyTraits::ALWAYS_SBO;
    summary.tinyForceHeap = TinyTraits::FORCE_HEAP;

    // For MediumPod, check conditional SBO vs forced heap.
    summary.mediumConditionalSbo = MediumTraits::CONDITIONAL_SBO;
    summary.mediumForceHeap      = MediumTraits::FORCE_HEAP;

    // LargePod should be forced to heap when it exceeds max SBO size.
    summary.largeForceHeap = LargeTraits::FORCE_HEAP;

    // Copy configuration thresholds from SBOConfig
    summary.alwaysThreshold      = SBOConfig::ALWAYS_SBO_SIZE;
    summary.conditionalThreshold = SBOConfig::CONDITIONAL_SBO_SIZE;
    summary.maxStackUsage        = SBOConfig::MAX_SBO_STACK_USAGE;

    return summary;
}

}  // namespace test_reaction
