#include <reaction/core/observer_node.h>
#include <reaction/graph/observer_graph.h>
#include <memory>
#include <string>

namespace test_reaction {

class ResetAwareNode : public reaction::ObserverNode {
public:
    explicit ResetAwareNode(std::string name)
        : reaction::ObserverNode(std::move(name)), notificationCount_(0) {}

    // Called by the graph when this node is notified/updated.
    void notify() override {
        ++notificationCount_;
        // Delegate to base in case it has important behavior
        reaction::ObserverNode::notify();
    }

    int notifications() const { return notificationCount_; }
    void clear() { notificationCount_ = 0; }

private:
    int notificationCount_;
};

struct ResetNodeResult {
    bool notifiedBeforeReset;
    bool notifiedAfterReset;
};

inline ResetNodeResult test_graph_reset_node(const std::string &sourceName,
                                             const std::string &targetName) {
    using namespace reaction;

    // 1. Create source and target ResetAwareNode instances
    NodePtr source = std::make_shared<ResetAwareNode>(sourceName);
    NodePtr target = std::make_shared<ResetAwareNode>(targetName);

    auto *sourceNode = static_cast<ResetAwareNode *>(source.get());
    auto *targetNode = static_cast<ResetAwareNode *>(target.get());

    // 2. Get observer graph instance
    auto &graph = ObserverGraph::getInstance();

    // 3. Register nodes
    graph.addNode(source);
    graph.addNode(target);

    // 4. Set up observer relationship (source -> target)
    graph.addObserver(source, target);

    // 5. Trigger notification on source
    graph.notifyNode(source);

    // 6. Check if target was notified before reset
    bool notifiedBeforeReset = (targetNode->notifications() > 0);

    // 7. Clear target notification count
    targetNode->clear();

    // 8. Reset target node
    graph.resetNode(target);

    // 9. Trigger notification on source again
    graph.notifyNode(source);

    // 10. Check if target was notified after reset
    bool notifiedAfterReset = (targetNode->notifications() > 0);

    // 11. Close nodes
    graph.removeNode(source);
    graph.removeNode(target);

    // 12. Return reset node result
    return ResetNodeResult{notifiedBeforeReset, notifiedAfterReset};
}

}  // namespace test_reaction
