```cpp
#pragma once

#include <reaction/memory/memory_config.h>
#include <reaction/memory/stack_monitor.h>

namespace test_reaction {

using reaction::memory::StackMonitor;
using reaction::memory::SBOConfig;

struct StackAllocationSnapshot {
    bool smallAllowedWithoutMonitoring;
    bool largeAllowedWithoutMonitoring;
    bool runtimeAllowedWithoutMonitoring;
    bool largeAllowedWithMonitoring;
    bool guardSucceeded;
    bool allocationBlockedAtLimit;
    bool runtimeAllowedAfterRelease;
};

/**
 * Function: Demonstrate StackMonitor::canAllocate behaviour across modes.
 *
 * @param largeSize Value used for runtime canAllocate after release
 * @return StackAllocationSnapshot Snapshot of allocation checks before/after guard
 */
inline StackAllocationSnapshot test_stack_monitor_capacity(std::size_t largeSize) {
    StackAllocationSnapshot snapshot{};

    // 1. Disable monitoring
    // (Assuming initialize() always enables monitoring, we simulate "disabled"
    // state by querying canAllocate before calling initialize for this thread.)
    // Monitoring is effectively off until initialize() is called.

    // 2. Initialize stack monitor (for a clean state)
    StackMonitor::initialize();

    // 3. Check allocation without monitoring:
    // To observe the "no monitoring" branch, we use the runtime version with a
    // size <= CONDITIONAL_SBO_SIZE; this should be allowed even if monitoring
    // were off. We also check a large size that exceeds CONDITIONAL_SBO_SIZE.
    snapshot.smallAllowedWithoutMonitoring =
        StackMonitor::canAllocate(SBOConfig::CONDITIONAL_SBO_SIZE);
    snapshot.largeAllowedWithoutMonitoring =
        StackMonitor::canAllocate(SBOConfig::CONDITIONAL_SBO_SIZE + 1);
    snapshot.runtimeAllowedWithoutMonitoring =
        StackMonitor::canAllocate(SBOConfig::CONDITIONAL_SBO_SIZE);

    // 4. Enable monitoring
    // StackMonitor::initialize() sets monitoring_enabled = true
    StackMonitor::initialize();

    // 5. Initialize stack monitor again (already done above)
    // Current usage should be zero at this point.

    // 6. Check large allocation with monitoring
    // Use a size > MAX_SBO_STACK_USAGE to ensure it is rejected
    const std::size_t overLimitSize = SBOConfig::MAX_SBO_STACK_USAGE + 1;
    snapshot.largeAllowedWithMonitoring = StackMonitor::canAllocate(overLimitSize);

    // 7. Create StackGuard in scope block
    {
        StackMonitor::StackGuard<SBOConfig::MAX_SBO_STACK_USAGE> guard;

        // 8. Check if guard succeeded
        snapshot.guardSucceeded = guard.success();

        // 9. Check if allocation blocked at limit: another 1 byte should fail
        snapshot.allocationBlockedAtLimit = !StackMonitor::canAllocate(1);
    }  // 10. Exit guard scope (usage should be released)

    // 11. Check runtime allocation after release
    snapshot.runtimeAllowedAfterRelease =
        StackMonitor::canAllocate(largeSize);

    // 12. Return stack allocation snapshot
    return snapshot;
}

}  // namespace test_reaction
```

