```cpp
#pragma once

#include <reaction/memory/memory_config.h>
#include <reaction/memory/stack_monitor.h>

namespace test_reaction {

struct StackLimitSnapshot {
    reaction::memory::StackMonitor::UsageStats statsBeforeGuard;
    reaction::memory::StackMonitor::UsageStats statsAfterGuard;
    bool templateAllocationAllowed;
    bool runtimeAllocationAllowed;
    bool guardHeld;
    bool allocationBlockedWhileGuardHeld;
};

inline StackLimitSnapshot test_stack_monitor_limits() {
    using reaction::memory::SBOConfig;
    using reaction::memory::StackMonitor;

    // 1. Enable monitoring (explicitly) and
    // 2. Initialize stack monitor for current thread
    StackMonitor::setMonitoringEnabled(true);
    StackMonitor::initialize();

    // 3. Get usage statistics before guard
    StackLimitSnapshot snapshot{};
    snapshot.statsBeforeGuard = StackMonitor::getStats();

    // Choose a size well within limits so we can exercise both allowed
    // allocations and a successful guard.
    constexpr size_t guardSize = 64;

    // 4. Check if template allocation is allowed
    snapshot.templateAllocationAllowed = StackMonitor::canAllocate<guardSize>();

    // 5. Check if runtime allocation is allowed
    snapshot.runtimeAllocationAllowed = StackMonitor::canAllocate(guardSize);

    // 6. Create large StackGuard instance
    StackMonitor::StackGuard<guardSize> guard;
    snapshot.guardHeld = guard.success();

    // 7. Check if guard succeeded (already stored in snapshot.guardHeld)

    // 8. Check if allocation blocked while guard is held
    // Use a size that would exceed the maximum if added to guardSize.
    const size_t overflowSize = SBOConfig::MAX_SBO_STACK_USAGE - guardSize + 1;
    snapshot.allocationBlockedWhileGuardHeld =
        !StackMonitor::canAllocate(overflowSize);

    // 9. Get usage statistics after guard (still within scope of guard)
    snapshot.statsAfterGuard = StackMonitor::getStats();

    // 10. Return stack limit snapshot
    return snapshot;
}

}  // namespace test_reaction
