    graph.addNode(observer);

    // 5. Attach single observer: connect observer as dependent of source1
    graph.addDependency(source1, observer);

    // 6. Trigger notification on first source
    source1->valueChanged(true);

    // 7. Get notification count after initial setup
    ObserverNodeLinkSnapshot snapshot{};
    snapshot.firstNotificationsAfterInitial = observer->notifications();

    // 8. Rewire dependencies:
    //    - detach observer from source1
    //    - attach observer to source2 and source3
    graph.removeDependency(source1, observer);
    graph.addDependency(source2, observer);
    graph.addDependency(source3, observer);

    // 9. Trigger notification on old source (source1)
    source1->valueChanged(true);

    // 10. Get notification count after old source notification
    snapshot.firstNotificationsAfterUpdate = observer->notifications();

    // 11. Trigger notification on second source
    source2->valueChanged(true);

    // 12. Get notification count after second source notification
    snapshot.secondNotificationsAfterUpdate = observer->notifications();

    // 13. Trigger notification on third source
    source3->valueChanged(true);

    // 14. Get notification count after third source notification
    snapshot.thirdNotificationsAfterUpdate = observer->notifications();

    // 15. Close all nodes (remove from graph)
    graph.removeNode(source1);
    graph.removeNode(source2);
    graph.removeNode(source3);
    graph.removeNode(observer);

    // 16. Return observer node link snapshot
    return snapshot;
}

}  // namespace test_reaction

