#pragma once

#include <reaction/cache/graph_cache.h>
#include <reaction/core/observer_node.h>
#include <memory>

namespace test_reaction {

struct NodeMetricsCacheSnapshot {
    std::size_t entriesBefore;
    std::size_t entriesAfterCache;
    std::size_t entriesAfterInvalidate;
    std::size_t hitCount;
    std::size_t missCount;
    double hitRatio;
    bool metricsCachedExists;
    bool metricsClearedAfterInvalidate;
};

NodeMetricsCacheSnapshot test_node_metrics_cache() {
    using namespace reaction;

    NodeMetricsCacheSnapshot snapshot{};

    // 1. Create NodeMetricsCache instance
    NodeMetricsCache cache;

    // 2. Create ObserverNode instance
    auto node = std::make_shared<ObserverNode>();

    // 3. Get cache statistics before caching
    auto statsBefore = cache.getStats();
    snapshot.entriesBefore = statsBefore.entries;
    std::size_t hitBefore = statsBefore.hitCount;
    std::size_t missBefore = statsBefore.missCount;

    // 4. Query metrics before caching
    auto metricsBefore = cache.get(node);
    (void)metricsBefore;  // suppress unused warning

    // 5. Cache node metrics
    NodeMetrics metricsToCache{};
    cache.put(node, metricsToCache);

    // 6. Query metrics after caching
    auto metricsAfter = cache.get(node);
    snapshot.metricsCachedExists = metricsAfter.has_value();

    // 7. Get cache statistics after caching
    auto statsAfterCache = cache.getStats();
    snapshot.entriesAfterCache = statsAfterCache.entries;

    // Determine hit/miss increments
    snapshot.hitCount = statsAfterCache.hitCount;
    snapshot.missCount = statsAfterCache.missCount;

    std::size_t totalLookups =
        (statsAfterCache.hitCount - hitBefore) +
        (statsAfterCache.missCount - missBefore);
    snapshot.hitRatio = totalLookups == 0
                            ? 0.0
                            : static_cast<double>(statsAfterCache.hitCount - hitBefore) /
                                  static_cast<double>(totalLookups);

    // 8. Invalidate all entries
    cache.invalidateAll();

    // 9. Query metrics after invalidation
    auto metricsAfterInvalidate = cache.get(node);

    // 10. Get cache statistics after invalidation
    auto statsAfterInvalidate = cache.getStats();
    snapshot.entriesAfterInvalidate = statsAfterInvalidate.entries;
    snapshot.metricsClearedAfterInvalidate = !metricsAfterInvalidate.has_value();

    // 11. Return node metrics cache snapshot
    return snapshot;
}

}  // namespace test_reaction
