namespace test_reaction {

using reaction::CacheBase;

struct GenericCacheStatsSnapshot {
    std::size_t entriesBefore;
    std::size_t entriesAfterInsert;
    std::size_t entriesAfterInvalidate;
    std::size_t hitCount;
    std::size_t missCount;
    double hitRatio;
    bool firstLookupWasMiss;
    bool secondLookupWasHit;
};

inline GenericCacheStatsSnapshot test_generic_cache_base() {
    // 1. Define IntCache class inheriting from CacheBase
    class IntCache : public CacheBase<int, int> {
    public:
        using Base = CacheBase<int, int>;

        // 2. Expose CacheBase methods using using declarations
        using Base::lookup;
        using Base::insert;
        using Base::invalidateAll;
        using Base::triggerCleanup;
        using Base::getStats;
    };

    // 3. Create IntCache instance
    IntCache cache;

    int key = 42;

    // 4. Get initial cache statistics
    auto statsBefore = cache.getStats();

    // 5. Perform initial lookup (expected miss)
    bool firstLookupWasMiss = (cache.lookup(key) == nullptr);

    // 6. Insert value into cache
    cache.insert(key, 123);

    // 7. Perform second lookup (expected hit)
    auto *valuePtr = cache.lookup(key);
    bool secondLookupWasHit = (valuePtr != nullptr && *valuePtr == 123);

    // 8. Get cache statistics after insertion
    auto statsAfterInsert = cache.getStats();

    // 9. Invalidate all cache entries
    cache.invalidateAll();

    // 10. Trigger cleanup
    cache.triggerCleanup();

    // 11. Get cache statistics after invalidation
    auto statsAfterInvalidate = cache.getStats();

    // 12. Return generic cache stats snapshot
    GenericCacheStatsSnapshot snapshot{};
    snapshot.entriesBefore = statsBefore.totalEntries;
    snapshot.entriesAfterInsert = statsAfterInsert.totalEntries;
    snapshot.entriesAfterInvalidate = statsAfterInvalidate.totalEntries;
    snapshot.hitCount = statsAfterInvalidate.hitCount;
    snapshot.missCount = statsAfterInvalidate.missCount;
    snapshot.hitRatio = statsAfterInvalidate.hitRatio;
    snapshot.firstLookupWasMiss = firstLookupWasMiss;
    snapshot.secondLookupWasHit = secondLookupWasHit;

    return snapshot;
}

}  // namespace test_reaction

