inline AtomicHelperSnapshot test_atomic_compound_helpers(int32_t initial) {
    // 1–2. Implemented IntAtomicImpl above and create an instance here
    IntAtomicImpl impl(initial);

    // 3–4. Apply atomic compound assignment (generic) and record whether it changed
    reaction::atomicCompoundAssign(
        impl,
        [](int32_t current) { return current + 5; }  // add 5
    );
    bool addReportedChange = impl.lastReportedChange();

    // 5–6. Apply atomic multiply assignment and record change
    reaction::atomicMultiplyAssign(impl, 3);  // multiply by 3
    bool multiplyReportedChange = impl.lastReportedChange();

    // 7–8. Apply atomic bitwise AND assignment and record change
    reaction::atomicBitwiseAndAssign(impl, 0xFF);  // mask lower 8 bits
    bool andReportedChange = impl.lastReportedChange();

    // 9–10. Apply atomic left shift assignment and record change
    reaction::atomicLeftShiftAssign(impl, 1);  // shift left by 1
    bool leftShiftReportedChange = impl.lastReportedChange();

    // 11–12. Apply atomic increment and record change
    reaction::atomicIncrement(impl);
    bool incrementReportedChange = impl.lastReportedChange();

    // 13. Get final value
    int32_t finalValue = impl.value();

    // 14. Return snapshot
    return AtomicHelperSnapshot{
        finalValue,
        addReportedChange,
        multiplyReportedChange,
        andReportedChange,
        leftShiftReportedChange,
        incrementReportedChange};
}

}  // namespace test_reaction
